//Parse attachment payload For Apple

/*
1. create one custom variable with name `attachments` and assign value `abc.attachments`
2. create one custom variable with name `securityNonComplianceReasonObject` and assign value `abc.securityscaninfo.securityFailedReason`
*/

var arr = [];
var parseDataAttachment = "";
var droppedAttachmentNames = []
var nonCompliantAttachmentArray = []
if (attachments !== null && attachments !== '') {
var attachments = JSON.parse(attachments);
}
if (securityNonComplianceReasonObject !== null && securityNonComplianceReasonObject !== 'null' && securityNonComplianceReasonObject !== 'NA') {
var securityNonComplianceReasonObject = JSON.parse(securityNonComplianceReasonObject);
var nonCompliantAttachmentArray = securityNonComplianceReasonObject.attachments
}

if (attachments.length > 0 && nonCompliantAttachmentArray.length > 0) {
for (var i = 0; i < nonCompliantAttachmentArray.length; i++) {
droppedAttachmentNames.push(
nonCompliantAttachmentArray[i].name
)
}
}

for (var i = 0; i < attachments.length; i++) {
arr[i] = {};
arr[i]["mimeType"] = attachments[i].mimeType;
arr[i]["fileName"] = attachments[i].name;
if (droppedAttachmentNames.length > 0 && droppedAttachmentNames.indexOf(attachments[i].name) != -1) {
arr[i]["url"] = "";
arr[i]["dropped"] = true;
} else {
arr[i]["url"] = attachments[i].url;
arr[i]["dropped"] = false;
}
}

//`parseDataAttachment` variable can be used as payload

if (arr.length) {
parseDataAttachment = JSON.stringify(arr);

} else {
var emptyArray = [];
parseDataAttachment = JSON.stringify(emptyArray);
}

